arguments.command:
cd /work && python -c "
import pandas as pd,numpy as np
p=pd.read_csv('b3_te_zt400_pool.csv')
pd.set_option('display.width',300)
def fmt(r):
    return ' '.join(f'{c}{r[c]:.2f}' for c in p.columns[1:] if r[c]>0.005)
for i,r in p.iterrows(): print(r.candidate_id, fmt(r))
"

